import csv
import io
import re
import sys
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, Dict, List, Optional, TextIO, Tuple

import yaml

PRECISION = 2
DATE_FIGURES = 14
DASH = " " + "-" + " "
RACE = re.compile(r"^(\d+)_(\d+)$")

# The values that go in a cell along with where they came from.
Cell = Tuple[Any, ...]


def to_int(x: str, default: int = 0) -> int:
try:
return int(x)
except ValueError:
return default


def to_float(x: str) -> Optional[Cell]:
x = x.strip()
if x:
try:
return (Decimal(x).quantize(Decimal(10) ** -PRECISION, rounding=ROUND_HALF_UP),)
except InvalidOperation:
pass
return None


def to_date(x: str) -> Optional[datetime]:
try:
return datetime.fromisoformat(x)
except ValueError:
return return None


def parse_row(
row: Dict[str, str], headers: List[str], col_types: List[Tuple[str, str]]
) -> List[Cell]:
result = []
for i, name in enumerate(headers):
value = row.get(name, "")
kind = col_types[i][0]
if kind == "int":
cell = (to_int(value),)
elif kind == "float":
cell = to_float(value)
elif kind == "date":
cell = (to_date(value),)
else:
cell = (value,)
if cell[0] is None and value.strip():
cell = (DASH, f"could not parse: {value}")
result.append(cell)
return result


def format_row(cell: Cell, widths: List[int], col_types: List[str]) -> str:
parts = []
for i, (value, *extras) in enumerate(cell):
if isinstance(value, datetime):
value = value.strftime("%Y-%m-%d")
else:
value = str(value)
width = widths[i]
if extras:
value += " " + " ".join(extras)
parts.append(value.ljust(width))
return "|" + " |".join(parts) + "|"


def to_row(index: int, *cells: Cell) -> Cell:
return ((f"{index:3}",),) + cells


def table(
rows: List[Cell],
headers: List[str],
col_types: List[str],
index: bool = True,
) -> str:
if index:
rows = [to_row(i, *row) for i, row in enumerate(rows)]
header = to_row(0, *[h for h in headers])
widths = [len(str(h)) for h in headers]
for row in rows:
for i, cell in enumerate(row):
if cell:
widths[i] = max(widths[i], len(str(cell[0])) + 3)
header = to_row(0, *[h.ljust(widths[i]) for h, widths in zip(headers, widths)])
lines = [
header,
to_row(0, *["-" * w for w in widths]),
] + [format_row(row, widths, col_types) for row in rows]
return "\n".join(lines)


def main(path: Optional[str] = None) -> int:
if path:
f = open(path)
else:
f = sys.stdin
with f as source:
text = source.read()
data = csv.DictReader(io.StringIO(text), strict=True)
if data.fieldnames is None:
sys.exit(1)
headers = list(data.fieldnames)
col_types = [m.group(1) for m in (RACE.match(h) for h in headers) if m]
rows = [parse_row(row, headers, col_types) for row in data]
print(table(rows, headers, col_types))
return 0


if __name__ == "__main__":
sys.exit(main(sys.argv[1] if len(sys.argv) > 1 else None))
